const b = ($input.first().json || {}).body || $input.first().json || {};
let items = Array.isArray(b.items) ? b.items : (typeof b.text === 'string' ? [{ text: b.text, url: b.url, title: b.title, author: b.author, site: b.site }] : []);
items = items.filter((i) => i && typeof i.text === 'string' && i.text.trim().length > 10).slice(0, 80).map((i) => ({
  text: i.text.slice(0, 1500),
  url: typeof i.url === 'string' ? i.url.slice(0, 500) : undefined,
  title: typeof i.title === 'string' ? i.title.slice(0, 200) : undefined,
  author: typeof i.author === 'string' ? i.author.slice(0, 120) : undefined,
  site: typeof i.site === 'string' ? i.site.slice(0, 120) : undefined,
}));
if (!items.length) return [];
const kind = b.kind === 'trade' ? 'trade' : b.kind === 'request' || b.kind === 'service' ? 'request' : null;
return [{ json: { payload: { items, source_label: typeof b.source === 'string' ? b.source.slice(0, 60) : 'Webhook', force_kind: kind } } }];
